sync_schema = check_table + '''\n      c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS hr_daily_sync_state (\n        main_company_id TEXT PRIMARY KEY,\n        version TEXT NOT NULL,\n        updated_at TEXT NOT NULL\n      )`),'''
